import{_ as t,o as a,c as r,ag as i}from"./chunks/framework.YEBM7mz9.js";const o="/react-rehydrate/infographics.png",f=JSON.parse('{"title":"Architecture & Infographics","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),n={name:"architecture.md"};function s(c,e,h,l,d,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="architecture-infographics" tabindex="-1">Architecture &amp; Infographics <a class="header-anchor" href="#architecture-infographics" aria-label="Permalink to &quot;Architecture &amp; Infographics&quot;">​</a></h1><p>Understanding the underlying mechanics of <code>react-rehydrate</code> is key to mastering its full potential. This page provides a visual and technical breakdown of our <strong>Controlled Island Architecture</strong>.</p><h2 id="the-rehydration-cycle" tabindex="-1">The Rehydration Cycle <a class="header-anchor" href="#the-rehydration-cycle" aria-label="Permalink to &quot;The Rehydration Cycle&quot;">​</a></h2><p><img src="'+o+'" alt="React Rehydrate Infographics"></p><h3 id="core-components-of-the-flow" tabindex="-1">Core Components of the Flow <a class="header-anchor" href="#core-components-of-the-flow" aria-label="Permalink to &quot;Core Components of the Flow&quot;">​</a></h3><ol><li><p><strong>Host Environment (The Shell)</strong>: Your server-side application (CMS, Rails, PHP, etc.) generates the initial HTML. This is the &quot;Source of Truth&quot; for layout and initial state.</p></li><li><p><strong>Markup Discovery</strong>: The <code>rehydrate</code> function performs a linear, non-blocking scan for elements with the <code>data-react-from-markup-container</code> attribute.</p></li><li><p><strong>Rehydrator Bridge</strong>: For each rehydratable node, the library invokes your custom <strong>Rehydrator</strong>. This acts as a middleware that maps DOM attributes to React props.</p></li><li><p><strong>Concurrent Mounting</strong>: React 18+ roots are created and mounted into the DOM regions. Each root is independent, providing fault tolerance and memory isolation.</p></li></ol><h2 id="technical-positioning" tabindex="-1">Technical Positioning <a class="header-anchor" href="#technical-positioning" aria-label="Permalink to &quot;Technical Positioning&quot;">​</a></h2><h3 id="island-architecture" tabindex="-1">Island Architecture <a class="header-anchor" href="#island-architecture" aria-label="Permalink to &quot;Island Architecture&quot;">​</a></h3><p>Unlike a Single Page Application (SPA), our architecture treats the page as a series of independent interactive &quot;islands&quot; floating in a sea of static HTML. This ensures that the page is usable even before the JavaScript has finished loading.</p><h3 id="progressive-enhancement" tabindex="-1">Progressive Enhancement <a class="header-anchor" href="#progressive-enhancement" aria-label="Permalink to &quot;Progressive Enhancement&quot;">​</a></h3><p>If a script fails to load or an error occurs in one component, <code>react-rehydrate</code> ensures the rest of the page remains functional. This safety net is essential for enterprise-grade applications where stability is a priority.</p><h3 id="why-this-matters-for-architects" tabindex="-1">Why this matters for Architects <a class="header-anchor" href="#why-this-matters-for-architects" aria-label="Permalink to &quot;Why this matters for Architects&quot;">​</a></h3><ul><li><strong>Performance</strong>: Reduced Main Thread blocking compared to full-page hydration.</li><li><strong>Scalability</strong>: Multiple teams can own different islands.</li><li><strong>Maintainability</strong>: Clear separation between server-side layout and client-side behavior.</li></ul>',13)])])}const g=t(n,[["render",s]]);export{f as __pageData,g as default};
